mkdir -p /tmp/em && cat > /tmp/em/model.py <<'PY'
import re, sys, html
from xml.etree import ElementTree as etree

STX='\x02'; ETX='\x03'
INLINE_PLACEHOLDER = STX+'klzzwxh:%s'+ETX
ESCAPED_CHARS = ['\\', '`', '*', '_', '{', '}', '[', ']', '(', ')', '>', '#', '+', '-', '.', '!']

EMPHASIS_RE       = r'(\*)([^\*]+)\1'
STRONG_RE         = r'(\*{2})(.+?)\1'
SMART_STRONG_RE   = r'(?<!\w)(_{2})(?!_)(.+?)(?<!_)\1(?!\w)'
SMART_EMPHASIS_RE = r'(?<!\w)(_)(?!_)(.+?)(?<!_)\1(?!\w)'
SMART_STRONG_EM_RE= r'(?<!\w)(\_)\1(?!\1)(.+?)(?<!\w)\1(?!\1)(.+?)\1{3}(?!\w)'
EM_STRONG_RE      = r'(\*)\1{2}(.+?)\1(.*?)\1{2}'
EM_STRONG2_RE     = r'(_)\1{2}(.+?)\1(.*?)\1{2}'
STRONG_EM_RE      = r'(\*)\1{2}(.+?)\1{2}(.*?)\1'
STRONG_EM2_RE     = r'(_)\1{2}(.+?)\1{2}(.*?)\1'
STRONG_EM3_RE     = r'(\*)\1(?!\1)([^*]+?)\1(?!\1)(.+?)\1{3}'
NOT_STRONG_RE     = r'((^|(?<=\s))(\*{1,3}|_{1,3})(?=\s|$))'
BACKTICK_RE       = r'(?:(?<!\\)((?:\\{2})+)(?=`+)|(?<!\\)(`+)(.+?)(?<!`)\2(?!`))'
ESCAPE_RE         = r'\\(.)'
F = re.DOTALL|re.UNICODE

class Item:
    def __init__(s,p,b,t): s.pattern=re.compile(p,F); s.builder=b; s.tags=t

class EmProc:
    def __init__(s,trig,pats): s.compiled_re=re.compile(trig,F); s.PATTERNS=pats
    def build_single(s,m,tag,idx):
        el1=etree.Element(tag); s.parse_sub_patterns(m.group(2),el1,None,idx); return el1
    def build_double(s,m,tags,idx):
        t1,t2=tags.split(','); el1=etree.Element(t1); el2=etree.Element(t2)
        s.parse_sub_patterns(m.group(2),el2,None,idx); el1.append(el2)
        if len(m.groups())==3: s.parse_sub_patterns(m.group(3),el1,el2,idx)
        return el1
    def build_double2(s,m,tags,idx):
        t1,t2=tags.split(','); el1=etree.Element(t1); el2=etree.Element(t2)
        s.parse_sub_patterns(m.group(2),el1,None,idx)
        text=m.group(3); el1.append(el2); s.parse_sub_patterns(text,el2,None,idx)
        return el1
    def parse_sub_patterns(s,data,parent,last,idx):
        offset=0; pos=0; length=len(data)
        while pos<length:
            if s.compiled_re.match(data,pos):
                matched=False
                for index,item in enumerate(s.PATTERNS):
                    if index<=idx: continue
                    m=item.pattern.match(data,pos)
                    if m:
                        text=data[offset:m.start(0)]
                        if text:
                            if last is not None: last.tail=text
                            else: parent.text=text
                        el=s.build_element(m,item.builder,item.tags,index)
                        parent.append(el); last=el
                        offset=pos=m.end(0); matched=True
                if not matched: pos+=1
            else: pos+=1
        text=data[offset:]
        if text:
            if last is not None: last.tail=text
            else: parent.text=text
    def build_element(s,m,builder,tags,index):
        if builder=='double2': return s.build_double2(m,tags,index)
        if builder=='double': return s.build_double(m,tags,index)
        return s.build_single(m,tags,index)
    def handleMatch(s,m,data):
        for index,item in enumerate(s.PATTERNS):
            m1=item.pattern.match(data,m.start(0))
            if m1:
                return s.build_element(m1,item.builder,item.tags,index), m1.start(0), m1.end(0)
        return None,None,None

AST=EmProc(r'\*',[Item(EM_STRONG_RE,'double','strong,em'),Item(STRONG_EM_RE,'double','em,strong'),
                  Item(STRONG_EM3_RE,'double2','strong,em'),Item(STRONG_RE,'single','strong'),
                  Item(EMPHASIS_RE,'single','em')])
UND=EmProc(r'_',[Item(EM_STRONG2_RE,'double','smart_strong,em'),Item(STRONG_EM2_RE,'double','smart_em,strong'),
                 Item(SMART_STRONG_EM_RE,'double2','strong,em'),Item(SMART_STRONG_RE,'single','strong'),
                 Item(SMART_EMPHASIS_RE,'single','em')])

class NotStrong:
    compiled_re=re.compile(NOT_STRONG_RE,F)
    def handleMatch(s,m,data): return m.group(1),m.start(0),m.end(0)
class Backtick:
    compiled_re=re.compile(BACKTICK_RE,F)
    def handleMatch(s,m,data):
        if m.group(3):
            el=etree.Element('code'); el.text=m.group(3).strip()
            return el,m.start(0),m.end(0)
        return m.group(1)+m.group(1),m.start(0),m.end(0)
class Escape:
    compiled_re=re.compile(ESCAPE_RE,F)
    def handleMatch(s,m,data):
        ch=m.group(1)
        if ch in ESCAPED_CHARS: return '%s%s%s'%(STX,ord(ch),ETX),m.start(0),m.end(0)
        return None,m.start(0),m.end(0)

PATTERNS=[Backtick(),Escape(),NotStrong(),AST,UND]

stash=[]
def stashNode(node):
    i=len(stash); stash.append(node); return INLINE_PLACEHOLDER%('%04d'%i)

def applyPattern(pat,data,startIndex):
    match=None
    for match in pat.compiled_re.finditer(data,startIndex):
        node,start,end=pat.handleMatch(match,data)
        if start is None or end is None:
            startIndex+=match.end(0); match=None; continue
        break
    if not match: return data,False,0
    if node is None: return data,True,end
    ph=stashNode(node)
    return data[:start]+ph+data[end:],True,0

def handleInline(data):
    pi=0; si=0
    while pi<len(PATTERNS):
        data,matched,si=applyPattern(PATTERNS[pi],data,si)
        if not matched: pi+=1
    return data

PH_RE=re.compile(STX+'klzzwxh:([0-9]+)'+ETX)
def ser(node):
    # serialize element tree node (recursive), resolving placeholders in text
    out='<%s>'%node.tag
    if node.text: out+=res(node.text)
    for ch in node:
        out+=ser(ch)
        if ch.tail: out+=res(ch.tail)
    out+='</%s>'%node.tag
    return out
def res(text):
    o=''; i=0
    for m in PH_RE.finditer(text):
        o+=esc(text[i:m.start()]); n=stash[int(m.group(1))]
        o+= n if isinstance(n,str) else ser(n)
        i=m.end()
    o+=esc(text[i:])
    return o
def esc(t):
    return t.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')

UNESC=re.compile(STX+r'(\d+)'+ETX)
def unescape(t): return UNESC.sub(lambda m: chr(int(m.group(1))), t)

def render(md):
    stash.clear()
    d=handleInline(md)
    out=res(d)
    return '<p>'+unescape(out)+'</p>'

if __name__=='__main__':
    import json
    for line in sys.stdin:
        s=json.loads(line)
        print(json.dumps(render(s)))
